schema_ddl:
CREATE TABLE clienti (
    id SERIAL PRIMARY KEY,
    nome TEXT NOT NULL,
    codice_fiscale TEXT NOT NULL UNIQUE,
    numero_sinistri INT CHECK (numero_sinistri >= 0)
);

CREATE TABLE polizze (
    id SERIAL PRIMARY KEY,
    cliente_id INT NOT NULL REFERENCES clienti(id),
    premio_totale NUMERIC(10,2) CHECK (premio_totale >= 0),
    data_polizza DATE NOT NULL
);
